    private static readonly FrozenDictionary<string, OperationClassificationRow> RowsById = Rows
        .GroupBy(row => row.OperationId, StringComparer.Ordinal)
        .Where(group => group.Count() == 1)
        .ToFrozenDictionary(group => group.Key, group => group.Single(), StringComparer.Ordinal);

    /// <summary>
    /// Returns the reviewed row for <paramref name="operationId"/>, or
    /// <see cref="OperationClassificationLookup.Unreviewed"/> when the operation
    /// has no row, more than one row, or a row with an unreviewed value.
    /// </summary>
    public static OperationClassificationLookup Find(string operationId)
    {
        ArgumentNullException.ThrowIfNull(operationId);

        return RowsById.TryGetValue(operationId, out var row) && row.IsComplete
            ? new OperationClassificationLookup(OperationClassificationStatus.Reviewed, row)
            : OperationClassificationLookup.Unreviewed;
    }
